<script lang="ts">
 import {invalidateAll} from '$app/navigation';
 let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();let vineyard=$state(''),latitude=$state(''),longitude=$state(''),busy=$state(false),message=$state('');
 let latest=$derived(model.weather.find(w=>w.vineyard_id===vineyard));
 function select(){const v=model.vineyards.find(v=>v.id===vineyard);if(v?.geometry?.coordinates?.[0]?.[0]){const [lon,lat]=v.geometry.coordinates[0][0];latitude=String(lat);longitude=String(lon);}}
 async function load(){busy=true;message='';try{const res=await fetch('/api/weather',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({vineyard_id:vineyard,latitude:Number(latitude),longitude:Number(longitude)})});if(!res.ok)message=t((await res.json()).message);else await invalidateAll();}catch{message=t('connectionError');}finally{busy=false;}}
 function checks(row:Record<string,any>){return model.weather_rules.filter(r=>r.vineyard_id===vineyard).map(r=>{const value=row[r.parameter];const known=value!==null&&value!==undefined;return {name:r.name,result:!known?'missing':(r.minimum!==null&&Number(value)<Number(r.minimum))||(r.maximum!==null&&Number(value)>Number(r.maximum))?'outside_range':'within_range'};});}
</script>
<section class="card"><h2>{t('weatherTitle')}</h2><p class="muted">{t('weatherHint')}</p><form onsubmit={(e)=>{e.preventDefault();load();}}><div class="grid"><label>{t('vineyard_id')}<select bind:value={vineyard} onchange={select} required><option value="">—</option>{#each model.vineyards as v}<option value={v.id}>{v.code} · {v.name}</option>{/each}</select></label><label>{t('latitude')}<input bind:value={latitude} required /></label><label>{t('longitude')}<input bind:value={longitude} required /></label></div><button disabled={busy}>{busy?t('saving'):t('loadWeather')}</button></form>{#if latest}<p>{latest.provider} · {latest.fetched_at}</p><a href={latest.source} target="_blank" rel="noreferrer">{t('source')}</a><details><summary>{t('stations')}</summary><pre>{JSON.stringify(latest.data.sources,null,2)}</pre></details><div class="scroll"><table><thead><tr><th>{t('measured_at')}</th><th>°C</th><th>mm</th><th>km/h</th><th>{t('source')}</th><th>{t('weather_rules')}</th></tr></thead><tbody>{#each latest.data.weather??[] as row}<tr><td>{row.timestamp}</td><td>{row.temperature??'—'}</td><td>{row.precipitation??'—'}</td><td>{row.wind_speed??'—'}</td><td>{row.source_id??latest.provider}</td><td>{#each checks(row) as check}<span>{check.name}: {t(check.result)} </span>{/each}</td></tr>{/each}</tbody></table></div>{/if}<p role="status">{message}</p></section>
<style>.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:16px}.scroll{overflow:auto;max-height:360px}table{font-size:12px;width:100%;border-collapse:collapse}th,td{padding:10px;text-align:left;border-bottom:1px solid #e1e7de;white-space:nowrap}pre{overflow:auto;max-height:250px}</style>
